PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,google_sub TEXT UNIQUE NOT NULL,email TEXT UNIQUE NOT NULL,email_verified INTEGER NOT NULL DEFAULT 0,name TEXT NOT NULL,image TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,disabled_at INTEGER);
CREATE TABLE auth_sessions(id TEXT PRIMARY KEY,token_hash TEXT UNIQUE NOT NULL,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE auth_oauth_states(state_hash TEXT PRIMARY KEY,nonce TEXT NOT NULL,verifier TEXT NOT NULL,callback_url TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT,personal_owner_id TEXT REFERENCES users(id),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE organization_members(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(organization_id,user_id));
CREATE TABLE documents(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),created_by TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,mime_type TEXT NOT NULL,content TEXT NOT NULL DEFAULT '',notes TEXT,document_date INTEGER,current_version_id TEXT,home_folder_id TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,is_deleted INTEGER NOT NULL DEFAULT 0,deleted_at INTEGER,deleted_by TEXT);
CREATE INDEX documents_org_home ON documents(organization_id,home_folder_id,is_deleted);
CREATE TABLE versions(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,storage_key TEXT UNIQUE NOT NULL,original_name TEXT NOT NULL,mime_type TEXT NOT NULL DEFAULT 'application/octet-stream',size INTEGER NOT NULL,sha256 TEXT,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,preview_key TEXT,extracted_text TEXT NOT NULL DEFAULT '',processing_status TEXT NOT NULL DEFAULT 'pending',processing_error TEXT);
CREATE TABLE uploads(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,organization_id TEXT NOT NULL,document_id TEXT NOT NULL,version_id TEXT NOT NULL,storage_key TEXT NOT NULL,upload_id TEXT NOT NULL,file_name TEXT NOT NULL,mime_type TEXT NOT NULL,size INTEGER NOT NULL,fingerprint TEXT NOT NULL,part_size INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'uploading',folder_id TEXT,replacement INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE INDEX uploads_owner ON uploads(user_id,organization_id,status);
CREATE VIRTUAL TABLE documents_fts USING fts5(document_id UNINDEXED,name,content,notes);
CREATE TRIGGER documents_insert AFTER INSERT ON documents BEGIN INSERT INTO documents_fts(document_id,name,content,notes) VALUES(new.id,new.name,new.content,new.notes); END;
CREATE TRIGGER documents_update AFTER UPDATE OF name,content,notes ON documents BEGIN DELETE FROM documents_fts WHERE document_id=new.id; INSERT INTO documents_fts(document_id,name,content,notes) VALUES(new.id,new.name,new.content,new.notes); END;
CREATE TRIGGER documents_delete AFTER DELETE ON documents BEGIN DELETE FROM documents_fts WHERE document_id=old.id; END;
CREATE TABLE tags(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,name TEXT NOT NULL,color TEXT,description TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(organization_id,name));
CREATE TABLE documents_tags(document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,tag_id TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE,PRIMARY KEY(document_id,tag_id));
CREATE TABLE custom_properties(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,name TEXT NOT NULL,description TEXT,type TEXT NOT NULL,options TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE document_custom_properties(document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,property_id TEXT NOT NULL REFERENCES custom_properties(id) ON DELETE CASCADE,value TEXT,PRIMARY KEY(document_id,property_id));
CREATE TABLE document_views(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,name TEXT NOT NULL,description TEXT,search_query TEXT NOT NULL DEFAULT '',sort_field TEXT NOT NULL DEFAULT 'createdAt',sort_order TEXT NOT NULL DEFAULT 'desc',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE share_links(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,organization_id TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),token TEXT UNIQUE NOT NULL,password_hash TEXT,is_enabled INTEGER NOT NULL DEFAULT 1,expires_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,last_accessed_at INTEGER);
CREATE TABLE service_tokens(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,organization_id TEXT NOT NULL,folder_id TEXT,token_hash TEXT UNIQUE NOT NULL,name TEXT NOT NULL,permissions TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER,revoked_at INTEGER);
CREATE TABLE jobs(id TEXT PRIMARY KEY,version_id TEXT REFERENCES versions(id) ON DELETE CASCADE,kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,error TEXT,lease_token TEXT,generation INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(version_id,kind));
CREATE TABLE chunks(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,version_id TEXT NOT NULL REFERENCES versions(id) ON DELETE CASCADE,organization_id TEXT NOT NULL,text TEXT NOT NULL,ordinal INTEGER NOT NULL);
CREATE INDEX chunks_doc_version ON chunks(document_id,version_id);
CREATE TABLE ai_usage(day TEXT PRIMARY KEY,audio_seconds INTEGER NOT NULL DEFAULT 0,vision_images INTEGER NOT NULL DEFAULT 0,chat_requests INTEGER NOT NULL DEFAULT 0);
CREATE INDEX auth_sessions_expiry ON auth_sessions(expires_at);
CREATE INDEX auth_states_expiry ON auth_oauth_states(expires_at);
CREATE TABLE folders(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),parent_id TEXT REFERENCES folders(id),name TEXT NOT NULL,is_home INTEGER NOT NULL DEFAULT 0,is_restricted INTEGER NOT NULL DEFAULT 0,created_by TEXT REFERENCES users(id),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX one_home_per_org ON folders(organization_id) WHERE is_home=1;
CREATE UNIQUE INDEX folder_sibling_name ON folders(organization_id,coalesce(parent_id,''),lower(name));
CREATE TABLE folder_acl(folder_id TEXT NOT NULL REFERENCES folders(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN ('reader','writer')),PRIMARY KEY(folder_id,user_id));
CREATE TABLE document_shortcuts(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,folder_id TEXT NOT NULL REFERENCES folders(id) ON DELETE CASCADE,created_by TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL,UNIQUE(document_id,folder_id));
CREATE TABLE comments(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,author_id TEXT NOT NULL REFERENCES users(id),parent_id TEXT REFERENCES comments(id),body TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,deleted_at INTEGER);
CREATE TABLE IF NOT EXISTS comment_anchors(comment_id TEXT PRIMARY KEY REFERENCES comments(id) ON DELETE CASCADE,version_id TEXT NOT NULL REFERENCES versions(id) ON DELETE CASCADE,quote TEXT NOT NULL,page INTEGER,start_offset INTEGER,end_offset INTEGER);
CREATE TABLE comment_mentions(comment_id TEXT NOT NULL REFERENCES comments(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(comment_id,user_id));
CREATE TABLE document_activity(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),event TEXT NOT NULL,comment_id TEXT REFERENCES comments(id) ON DELETE CASCADE,created_at INTEGER NOT NULL);
CREATE TABLE activity_inbox(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,activity_id TEXT NOT NULL REFERENCES document_activity(id) ON DELETE CASCADE,read_at INTEGER,UNIQUE(user_id,activity_id));
CREATE TABLE IF NOT EXISTS signing_requests(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,version_id TEXT NOT NULL REFERENCES versions(id),name TEXT NOT NULL,source_sha256 TEXT NOT NULL,fields TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),sender_name TEXT NOT NULL,sender_email TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,completed_at INTEGER,signed_version_id TEXT,signed_key TEXT,signed_sha256 TEXT,signed_size INTEGER,audit_key TEXT,lease_token TEXT,attempts INTEGER NOT NULL DEFAULT 0,error TEXT,request_key TEXT NOT NULL,UNIQUE(created_by,request_key));
CREATE INDEX IF NOT EXISTS signing_requests_document ON signing_requests(document_id,created_at);
CREATE TABLE IF NOT EXISTS signing_recipients(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES signing_requests(id) ON DELETE CASCADE,position INTEGER NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL,signed_at INTEGER,signature TEXT,values_json TEXT,address TEXT,user_agent TEXT,rejected_at INTEGER,UNIQUE(request_id,position));
CREATE TABLE IF NOT EXISTS signing_mail(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES signing_requests(id) ON DELETE CASCADE,recipient_id TEXT NOT NULL REFERENCES signing_recipients(id) ON DELETE CASCADE,kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,lease_token TEXT,updated_at INTEGER NOT NULL,provider_id TEXT,error TEXT,UNIQUE(request_id,recipient_id,kind));

CREATE TABLE IF NOT EXISTS authored_versions ( version_id TEXT PRIMARY KEY REFERENCES versions(id) ON DELETE CASCADE, document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE, source_json TEXT NOT NULL, created_at INTEGER NOT NULL );
CREATE INDEX IF NOT EXISTS authored_document ON authored_versions(document_id,created_at);
CREATE TABLE IF NOT EXISTS document_edit_locks ( document_id TEXT PRIMARY KEY REFERENCES documents(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), token TEXT NOT NULL, expires_at INTEGER NOT NULL );

CREATE TABLE IF NOT EXISTS document_reviews ( id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE, version_id TEXT NOT NULL REFERENCES versions(id), created_by TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'open', created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS review_proposals ( id TEXT PRIMARY KEY, review_id TEXT NOT NULL REFERENCES document_reviews(id) ON DELETE CASCADE, name TEXT NOT NULL, comment TEXT NOT NULL, source_json TEXT, status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, resolved_at INTEGER, resolved_by TEXT REFERENCES users(id), published_version_id TEXT REFERENCES versions(id) );
CREATE INDEX IF NOT EXISTS review_document ON document_reviews(document_id,status);
